window.OVA_CONTENT={"slug":"seccion-06-innovacion-biologica-etica-y-proyecto","title":"Innovación biológica, ética y proyecto","minutes":50,"summary":"Integra ecología, información molecular y bioeconomía para formular mejoras responsables y verificables.","objective":"Construir una propuesta de innovación biológica con evidencia, actores, riesgos e indicadores.","stages":[{"eyebrow":"Problema","title":"1. Comprender antes de proponer","reading":"Una innovación pertinente parte de una situación delimitada: proceso, actores, evidencia, causas plausibles y efecto esperado. Una solución elegida antes del diagnóstico puede crear nuevos problemas.","application":"El análisis del micro y macroambiente ayuda a reconocer capacidades internas y condiciones externas.","activity":{"type":"order","question":"Ordena el inicio del proyecto.","items":["Delimitar situación","Identificar actores","Reunir evidencia","Analizar causas y restricciones","Definir objetivo de mejora"],"answer":[0,1,2,3,4],"success":"El problema orienta la tecnología, no al contrario."}},{"eyebrow":"Criterios","title":"2. Beneficio, daño y justicia","reading":"La beneficencia orienta a producir beneficios; la no maleficencia exige prevenir daños; la justicia examina cómo se distribuyen riesgos y beneficios.","application":"Estos criterios permiten discutir una tecnología sin reducir la decisión a aceptación o rechazo.","activity":{"type":"match","question":"Relaciona principio y pregunta.","pairs":[{"label":"Beneficencia","value":"beneficio","option":"¿Qué mejora produce?"},{"label":"No maleficencia","value":"danos","option":"¿Qué daños deben prevenirse?"},{"label":"Justicia","value":"distribucion","option":"¿Quién recibe riesgos y beneficios?"}],"answer":["beneficio","danos","distribucion"],"success":"La ética estructura preguntas verificables."}},{"eyebrow":"Viabilidad","title":"3. Condiciones para implementar","reading":"Una propuesta debe considerar recursos, capacidades, regulación, operación, mantenimiento, aceptación de actores e indicadores. La demostración técnica no garantiza adopción sostenible.","application":"También debe establecer qué incertidumbres permanecen y cómo se monitorearán. La organización debe documentar la línea base, los supuestos y el seguimiento para convertir la evidencia biológica en una decisión sostenible verificable.","activity":{"type":"multi","question":"Selecciona componentes necesarios.","options":["Responsables y recursos","Indicadores de resultado","Gestión de riesgos","Cronograma de lanzamiento sin línea base ni criterio de éxito"],"answer":[0,1,2],"success":"La implementación necesita condiciones y seguimiento."}},{"eyebrow":"Indicadores","title":"4. Saber si la mejora funciona","reading":"Un indicador útil se relaciona con el objetivo, tiene unidad, fuente, frecuencia y valor de referencia. Conviene combinar desempeño productivo, uso de recursos y efectos ambientales.","application":"Sin línea base no puede distinguirse mejora de variación normal. La organización debe documentar la línea base, los supuestos y el seguimiento para convertir la evidencia biológica en una decisión sostenible verificable.","activity":{"type":"choice","question":"¿Cuál indicador está mejor formulado?","options":["Litros de agua por kilogramo de producto, medidos semanalmente","Porcentaje de sostenibilidad estimado por el equipo al cierre del proyecto","Consumo total de agua sin relacionarlo con volumen producido ni periodo comparable"],"answer":[0],"success":"Un indicador operativo permite comparar."}},{"eyebrow":"Proyecto final","title":"5. Propuesta argumentada","reading":"La propuesta final integra problema, fundamento biológico, alternativa, evidencia, actores, riesgos, viabilidad e indicadores. Debe comunicar límites y condiciones, no prometer certeza absoluta.","application":"La calidad se evidencia en la relación entre diagnóstico, decisión y seguimiento. La organización debe documentar la línea base, los supuestos y el seguimiento para convertir la evidencia biológica en una decisión sostenible verificable.","activity":{"type":"order","question":"Ordena la estructura del proyecto.","items":["Problema y contexto","Fundamento biológico","Alternativa y evidencia","Riesgos, ética y viabilidad","Indicadores y seguimiento"],"answer":[0,1,2,3,4],"success":"La propuesta queda lista para discusión y mejora."}},{"eyebrow":"Actores","title":"6. Innovar con quienes reciben efectos","reading":"Una innovación distribuye beneficios, costos y riesgos entre productores, trabajadores, comunidades, consumidores y ecosistemas. Su interpretación exige comparar escalas, referencias y series de datos, porque una observación aislada no demuestra causalidad ni representa por sí sola el comportamiento del sistema.","application":"Incluir actores temprano permite detectar barreras y criterios que una evaluación exclusivamente técnica no observa.","visual":{"label":"Innovar con quienes reciben efectos","items":["Problema","Actores","Alternativas","Seguimiento"]},"activity":{"type":"choice","question":"¿Qué participación aporta más a una innovación responsable?","options":["Involucrar actores en definición del problema, criterios y seguimiento","Informar la decisión cuando ya no puede modificarse","Consultar únicamente a quienes financian la tecnología"],"answer":[0],"success":"La participación temprana puede cambiar tanto el diseño como la evaluación."}},{"eyebrow":"Precaución","title":"7. Incertidumbre no equivale a inmovilidad","reading":"Ante daño potencial serio y evidencia incompleta, la precaución orienta medidas proporcionales, investigación y monitoreo. No exige riesgo cero. Su interpretación exige comparar escalas, referencias y series de datos, porque una observación aislada no demuestra causalidad ni representa por sí sola el comportamiento del sistema.","application":"Pilotos acotados, barreras y criterios de detención permiten aprender sin exponer todo el sistema.","activity":{"type":"multi","question":"¿Qué acciones expresan una precaución proporcional?","options":["Implementación gradual con límites definidos","Monitoreo de efectos esperados y no previstos","Criterios previos para detener o ajustar","Adopción total porque aún no se ha demostrado daño"],"answer":[0,1,2],"success":"La precaución combina aprendizaje, proporcionalidad y capacidad de corrección."}},{"eyebrow":"Proyecto final","title":"8. Una propuesta que pueda evaluarse","reading":"La propuesta integra problema, fundamento biológico, alternativa, indicadores, riesgos, actores y plan de implementación. Debe diferenciar supuestos de evidencia.","application":"Una recomendación útil permite decidir qué probar, cómo saber si funciona y cuándo detenerse.","activity":{"type":"order","question":"Ordena la presentación de una propuesta de innovación.","items":["Delimitar problema y línea base","Explicar mecanismo biológico y alternativa","Comparar beneficios, riesgos y actores","Definir piloto, indicadores y umbrales","Comunicar resultados y ruta de escalamiento"],"answer":[0,1,2,3,4],"success":"La propuesta conecta conocimiento biológico con una decisión verificable y responsable."}}],"number":"06","references":["Cunningham, W. P. et al. (2023). Principios de Ciencias Ambientales. McGraw-Hill.","Smith, T. M. y Smith, R. L. (2007). Ecología. Pearson.","Hardin, J. y Lodolce, J. P. (2024). Becker. El mundo de la célula. Pearson.","Marino Buslje, C. y Parisi, G. (2019). Aprender para predecir: la bioinformática como herramienta de estudio en biología.","Hodson de Jaramillo, E. et al. (2019). La bioeconomía: nuevo marco para el crecimiento sostenible en América Latina."]};